    53|/**
    54| * Hard ceiling on a single owner-AI JSON response body. The upstream proxy/host
    55| * truncates very large bodies mid-stream, which produces an invalid-JSON reply
    56| * the client "cannot read" (the "temporary backend formatting issue" the owner
    57| * saw). We keep responses safely under that ceiling.
    58| */
    59|const OWNER_ONLY_MAX_RESPONSE_BYTES = 900_000;
    60|
    61|/**
    62| * Serialize an owner response to JSON that the client can ALWAYS parse.
    63| *
    64| * Guarantees, in order:
    65| *   1. JSON.stringify never throws (circular refs / BigInt / bad getters fall
    66| *      back to a minimal canonical envelope instead of a 500 / empty body).
    67| *   2. The body never exceeds OWNER_ONLY_MAX_RESPONSE_BYTES — when it would,
    68| *      heavy diagnostic-only fields are dropped and the visible `answer` is
    69| *      safely truncated, preserving the canonical contract
    70| *      (requestId/conversationId/answer/model/status).
    71| */
    72|function serializeOwnerOnlyPayload(payload: Record<string, unknown>): string {
    73|  let body: string;
    74|  try {
    75|    body = JSON.stringify(payload);
    76|  } catch (error) {
    77|    return JSON.stringify(buildMinimalOwnerEnvelope(payload, error));
    78|  }
    79|
    80|  if (body.length <= OWNER_ONLY_MAX_RESPONSE_BYTES) {
    81|    return body;
    82|  }
    83|
    84|  // Oversized: strip diagnostic-only fields that are never required to render a
    85|  // reply, then re-serialize. `answer` is preserved (truncated if needed).
    86|  const slim: Record<string, unknown> = { ...payload };
    87|  for (const heavyField of ['toolOutputs', 'toolOutput', 'toolInput', 'runtimeV2', 'routerDebug', 'diagnostics', 'providerError']) {
    88|    delete slim[heavyField];
    89|  }
    90|  if (typeof slim.answer === 'string' && slim.answer.length > 40_000) {
    91|    slim.answer = `${slim.answer.slice(0, 40_000)}\n\n…[truncated for transport — full result preserved server-side]`;
    92|  }
    93|  slim.responseTruncated = true;
    94|
    95|  try {
    96|    const slimBody = JSON.stringify(slim);
    97|    if (slimBody.length <= OWNER_ONLY_MAX_RESPONSE_BYTES) {
    98|      return slimBody;
    99|    }
