   106|function buildMinimalOwnerEnvelope(payload: Record<string, unknown>, error: unknown): Record<string, unknown> {
   107|  const reason = error instanceof Error ? error.message : null;
   108|  const answer = typeof payload.answer === 'string' && payload.answer.trim()
   109|    ? payload.answer.slice(0, 20_000)
   110|    : 'The IVX Owner AI completed, but its full response was too large or could not be serialized. The result was preserved server-side — please resend.';
   111|  return {
   112|    requestId: typeof payload.requestId === 'string' ? payload.requestId : `ivx-${Date.now()}`,
   113|    conversationId: typeof payload.conversationId === 'string' ? payload.conversationId : 'ivx-owner-ai',
   114|    answer,
   115|    model: typeof payload.model === 'string' ? payload.model : 'ivx_owner_ai_safe_envelope',
   116|    status: payload.status === 'error' ? 'error' : 'ok',
   117|    source: 'local_app_brain',
   118|    responseTruncated: true,
   119|    serializationFallback: reason ? `serialize_failed: ${reason}`.slice(0, 240) : 'serialize_size_guard',
   120|  };
